import React, { useEffect, useRef } from "react";
import "./HeroSection.css";
import * as THREE from "three";
// @ts-ignore
import CELLS from 'vanta/dist/vanta.cells.min';

const HeroSection = () => {
  const vantaRef = useRef(null);
  const vantaEffect = useRef(null);

  useEffect(() => {
  console.log("Inicializando Vanta...", vantaRef.current);

  if (vantaRef.current && !vantaEffect.current) {
    vantaEffect.current = CELLS({
        el: vantaRef.current,
        THREE,
        mouseControls: true,
        touchControls: true,
        gyroControls: false,
        color1: 0x0077ff,   // Azul
        color2: 0xff7700,   // Laranja
        minHeight: 500.0,
        minWidth: 500.0,
        scale: 5.0,
        scaleMobile: 1.0,
      });
    console.log("Vanta inicializado!");
  }

  return () => {
    if (vantaEffect.current) {
      vantaEffect.current.destroy();
      vantaEffect.current = null;
    }
  };
}, []);


  return (
    <div ref={vantaRef} className="vanta-wrapper">
      <div class="noise"></div>
      <div className="portfolio-container">
        {/* Hero com título */}
        <div className="hero-content">
          <h1 className="title">
            <div className="gradient-circle"></div>
            Port<br />Fólio
          </h1>
          <h2 className="subtitle">
            Front-end Developer <br /> <span>And Designer UI/UX</span>
          </h2>
        </div>

        {/* Rodapé */}
        <footer className="footer">
          <div className="footer-left">
            <div>
              <span className="year">2025<br /></span>
              <span>Victor Gabriel</span>
            </div>
            <div>
              <i className="bi bi-circle-half"></i>
              <i className="bi bi-brightness-high-fill"></i>
              <i className="bi bi-bullseye"></i>
            </div>
          </div>
          <div className="footer-right">
            <i className="bi bi-arrow-90deg-down"></i>
            <a href="#projects">Ver projetos</a>
          </div>
        </footer>
      </div>
    </div>
  );
};

export default HeroSection;
